function sumCounts(nums) {
  const MOD = 1_000_000_007;
  const n = nums.length;
  const sum = new Array(4 * n).fill(0);
  const lazy = new Array(4 * n).fill(0);

  function apply(node, low, high, delta) {
    sum[node] += delta * (high - low + 1);
    lazy[node] += delta;
  }

  // Adds 1 to every count in [from, to] and returns their total from before the add.
  function addOne(node, low, high, from, to) {
    if (to < low || high < from) return 0;
    if (from <= low && high <= to) {
      const before = sum[node];
      apply(node, low, high, 1);
      return before;
    }
    const mid = (low + high) >> 1;
    if (lazy[node] !== 0) {
      apply(2 * node, low, mid, lazy[node]);
      apply(2 * node + 1, mid + 1, high, lazy[node]);
      lazy[node] = 0;
    }
    const before = addOne(2 * node, low, mid, from, to) + addOne(2 * node + 1, mid + 1, high, from, to);
    sum[node] = sum[2 * node] + sum[2 * node + 1];
    return before;
  }

  const lastSeen = new Map();
  let squares = 0;
  let answer = 0;
  for (let right = 0; right < n; right++) {
    const prev = lastSeen.has(nums[right]) ? lastSeen.get(nums[right]) : -1;
    const total = addOne(1, 0, n - 1, prev + 1, right);
    squares = (squares + 2 * total + (right - prev)) % MOD;
    answer = (answer + squares) % MOD;
    lastSeen.set(nums[right], right);
  }
  return answer;
}

